import org.junit.Test;
import static org.junit.Assert.*;
import java.util.List;

public class DirectivesBuilderTest {

    @Test
    public void buildDirectivesNoAnnotations() {
        DirectivesBuilder builder = new DirectivesBuilder(new Object(), null);
        GraphQLDirective[] result = builder.build();
        assertEquals(0, result.length);
    }

    @Test
    public void buildDirectivesMultipleAnnotationTypes() {
        GraphQLDirectives directives = new GraphQLDirectives("directives");
        AnnotatedElement element = Mockito.mock(AnnotatedElement.class);
        ProcessingElementsContainer container = Mockito.mock(ProcessingElementsContainer.class);
        DirectivesBuilder builder = new DirectivesBuilder(element, container);
        builder.setAnnotation(directives);
        GraphQLDirective[] result = builder.build();
        assertEquals(directives.getTypes().size(), result.length);
    }

    @Test
    public void buildDirectivesNoArgumentTypes() {
        GraphQLDirectives directives = new GraphQLDirectives("directives");
        AnnotatedElement element = Mockito.mock(AnnotatedElement.class);
        ProcessingElementsContainer container = Mockito.mock(ProcessingElementsContainer.class);
        DirectivesBuilder builder = new DirectivesBuilder(element, container);
        builder.setAnnotation(directives);
        assertEquals(Arrays.asList(), buildArgumentTypes(directives));
    }

    @Test
    public void buildDirectivesWithArgumentType() {
        GraphQLArgument argumentType = Mockito.mock(GraphQLArgument.class);
        GraphQLDirectives directives = new GraphQLDirectives("directives");
        AnnotatedElement element = Mockito.mock(AnnotatedElement.class);
        ProcessingElementsContainer container = Mockito.mock(ProcessingElementsContainer.class);
        DirectivesBuilder builder = new DirectivesBuilder(element, container);
        builder.setAnnotation(directives);
        addArgumentType(directives, argumentType);
        GraphQLDirective[] result = builder.build();
        assertEquals(1, result.length);
    }

    @Test
    public void buildDirectivesMultipleArgumentTypes() {
        GraphQLArgument arg1 = Mockito.mock(GraphQLArgument.class);
        GraphQLArgument arg2 = Mockito.mock(GraphQLArgument.class);
        addArgumentType(new GraphQLDirectives("directives"), arg1);
        addArgumentType(new GraphQLDirectives("directives"), arg2);
        AnnotatedElement element = Mockito.mock(AnnotatedElement.class);
        ProcessingElementsContainer container = Mockito.mock(ProcessingElementsContainer.class);
        DirectivesBuilder builder = new DirectivesBuilder(element, container);
        builder.setAnnotation(new GraphQLDirectives("directives"));
        GraphQLDirective[] result = builder.build();
        assertEquals(2, result.length);
    }

    @Test
    public void buildArgumentTypes() {
        GraphQLDirectives directives = new GraphQLDirectives("directives");
        List<GraphQLType> argumentTypes = Arrays.asList(Mockito.mock(GraphQLType.class), Mockito.mock(GraphQLType.class));
        assertSame(argumentTypes, buildArgumentTypes(directives));
    }

    @Test
    public void buildArgumentTypesEmpty() {
        GraphQLDirectives directives = new GraphQLDirectives("directives");
        assertTrue(buildArgumentTypes(directives).isEmpty());
    }

    private List<GraphQLType> buildArgumentTypes(GraphQLDirectives directives) {
        return Arrays.stream(directives.getTypes()).collect(Collectors.toList());
    }

    private void addArgumentType(GraphQLDirectives directives, GraphQLArgument argumentType) {
        directives.getType().add(argumentType);
    }
}
